import React from 'react';
import ReactDOM from 'react-dom/client';
import { HashRouter } from 'react-router-dom';
import App from './App';
import ErrorBoundary from './components/ErrorBoundary';

// Mobile debugging
console.log('Mobile Debug - User Agent:', navigator.userAgent);
console.log('Mobile Debug - Screen:', window.screen.width + 'x' + window.screen.height);
console.log('Mobile Debug - Viewport:', window.innerWidth + 'x' + window.innerHeight);

// Global error handlers for mobile
window.addEventListener('error', (event) => {
  console.error('Global Error:', event.error);
  console.error('Error details:', {
    message: event.message,
    filename: event.filename,
    lineno: event.lineno,
    colno: event.colno,
    stack: event.error?.stack
  });
});

window.addEventListener('unhandledrejection', (event) => {
  console.error('Unhandled Promise Rejection:', event.reason);
});

const initApp = () => {
  try {
    const rootElement = document.getElementById('root');
    if (!rootElement) {
      console.error('Root element not found');
      return;
    }

    console.log('Creating React root...');
    const root = ReactDOM.createRoot(rootElement);
    
    console.log('Rendering app...');
    root.render(
      <ErrorBoundary>
        <HashRouter>
          <App />
        </HashRouter>
      </ErrorBoundary>
    );
    
    console.log('App rendered successfully');
  } catch (error) {
    console.error('Failed to initialize app:', error);
    
    // Fallback rendering for mobile
    const rootElement = document.getElementById('root');
    if (rootElement) {
      rootElement.innerHTML = `
        <div style="
          position: fixed;
          top: 0;
          left: 0;
          width: 100vw;
          height: 100vh;
          background: #f5f5f5;
          display: flex;
          align-items: center;
          justify-content: center;
          flex-direction: column;
          padding: 20px;
          text-align: center;
          font-family: -apple-system, BlinkMacSystemFont, sans-serif;
          z-index: 9999;
        ">
          <div style="
            background: #fff;
            padding: 30px;
            border-radius: 12px;
            box-shadow: 0 4px 16px rgba(0,0,0,0.1);
            max-width: 350px;
            width: 100%;
          ">
            <h2 style="color: #e74c3c; margin-bottom: 16px; font-size: 18px;">
              🚨 로딩 오류
            </h2>
            <p style="color: #7f8c8d; margin-bottom: 20px; font-size: 14px;">
              앱을 로드하는 중 오류가 발생했습니다.<br>
              브라우저를 새로고침해주세요.
            </p>
            <button onclick="window.location.reload()" style="
              background: #4facfe;
              color: white;
              border: none;
              padding: 12px 24px;
              border-radius: 8px;
              font-size: 14px;
              font-weight: 600;
              cursor: pointer;
              width: 100%;
              margin-bottom: 10px;
            ">
              새로고침
            </button>
            <button onclick="window.location.href='https://22500735.github.io/demo3/'" style="
              background: #95a5a6;
              color: white;
              border: none;
              padding: 12px 24px;
              border-radius: 8px;
              font-size: 14px;
              font-weight: 600;
              cursor: pointer;
              width: 100%;
            ">
              홈으로 이동
            </button>
          </div>
        </div>
      `;
    }
  }
};

// Wait for DOM to be ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initApp);
} else {
  initApp();
}
