import React, { useState, useEffect, Suspense } from 'react';
import { Routes, Route, useLocation } from 'react-router-dom';
import Navigation from './components/Navigation';
import './App.css';

// Lazy load components for better mobile performance
const MainFeed = React.lazy(() => import('./components/MainFeed'));
const Board = React.lazy(() => import('./components/Board'));
const Timetable = React.lazy(() => import('./components/Timetable'));
const Marketplace = React.lazy(() => import('./components/Marketplace'));
const Map = React.lazy(() => import('./components/Map'));
const MyPage = React.lazy(() => import('./components/MyPage'));
const SeasonalTheme = React.lazy(() => import('./components/SeasonalTheme'));
const JapaneseMascot = React.lazy(() => import('./components/JapaneseMascot'));
const PushNotifications = React.lazy(() => import('./components/PushNotifications'));
const OfflineSupport = React.lazy(() => import('./components/OfflineSupport'));

function App() {
  const [currentTab, setCurrentTab] = useState('home');
  const [darkMode, setDarkMode] = useState(() => {
    const saved = localStorage.getItem('darkMode');
    return saved ? JSON.parse(saved) : false;
  });
  const [user, setUser] = useState({
    id: 1,
    name: '田中太郎',
    username: '@tanaka_taro',
    avatar: '👤',
    department: '工学部',
    year: 3,
    isAnonymous: false
  });
  const location = useLocation();

  useEffect(() => {
    const path = location.pathname;
    if (path === '/' || path === '/demo3/') setCurrentTab('home');
    else if (path === '/board' || path === '/demo3/board') setCurrentTab('board');
    else if (path === '/timetable' || path === '/demo3/timetable') setCurrentTab('timetable');
    else if (path === '/marketplace' || path === '/demo3/marketplace') setCurrentTab('marketplace');
    else if (path === '/map' || path === '/demo3/map') setCurrentTab('map');
    else if (path === '/mypage' || path === '/demo3/mypage') setCurrentTab('mypage');
  }, [location]);

  useEffect(() => {
    localStorage.setItem('darkMode', JSON.stringify(darkMode));
    document.documentElement.setAttribute('data-theme', darkMode ? 'dark' : 'light');
  }, [darkMode]);

  const toggleDarkMode = () => {
    setDarkMode(prev => !prev);
  };

  // Loading fallback component for mobile
  const LoadingFallback = ({ error }) => (
    <div style={{
      position: 'fixed',
      top: 0,
      left: 0,
      width: '100vw',
      height: '100vh',
      background: darkMode ? '#1a1a1a' : '#f5f5f5',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      flexDirection: 'column',
      padding: '20px',
      textAlign: 'center',
      fontFamily: '-apple-system, BlinkMacSystemFont, sans-serif',
      zIndex: 9999
    }}>
      <div style={{
        background: darkMode ? '#2d2d2d' : '#fff',
        padding: '30px',
        borderRadius: '12px',
        boxShadow: '0 4px 16px rgba(0,0,0,0.1)',
        maxWidth: '350px',
        width: '100%',
        color: darkMode ? '#fff' : '#333'
      }}>
        {error ? (
          <>
            <h2 style={{ color: '#e74c3c', marginBottom: '16px', fontSize: '18px' }}>
              🚨 로딩 오류
            </h2>
            <p style={{ color: '#7f8c8d', marginBottom: '20px', fontSize: '14px' }}>
              컴포넌트를 로드하는 중 오류가 발생했습니다.<br />
              새로고침을 시도해주세요.
            </p>
          </>
        ) : (
          <>
            <div style={{ 
              fontSize: '24px', 
              marginBottom: '16px',
              animation: 'spin 1s linear infinite'
            }}>
              ⏳
            </div>
            <p style={{ color: '#7f8c8d', marginBottom: '20px', fontSize: '14px' }}>
              로딩 중...
            </p>
          </>
        )}
        <button 
          onClick={() => window.location.reload()} 
          style={{
            background: '#4facfe',
            color: 'white',
            border: 'none',
            padding: '12px 24px',
            borderRadius: '8px',
            fontSize: '14px',
            fontWeight: '600',
            cursor: 'pointer',
            width: '100%'
          }}
        >
          새로고침
        </button>
      </div>
    </div>
  );

  return (
    <Suspense fallback={<LoadingFallback />}>
      <SeasonalTheme>
        <div className={`app ${darkMode ? 'dark-mode' : ''}`}>
          <div className="app-container">
            {/* Dark Mode Toggle */}
            <button 
              className="dark-mode-toggle"
              onClick={toggleDarkMode}
              aria-label={darkMode ? 'ライトモードに切り替え' : 'ダークモードに切り替え'}
            >
              {darkMode ? '☀️' : '🌙'}
            </button>
            
            <main className="main-content">
              <Suspense fallback={<LoadingFallback />}>
                <Routes>
                  <Route path="/" element={<MainFeed user={user} setUser={setUser} darkMode={darkMode} />} />
                  <Route path="/board" element={<Board user={user} darkMode={darkMode} />} />
                  <Route path="/timetable" element={<Timetable user={user} darkMode={darkMode} />} />
                  <Route path="/marketplace" element={<Marketplace user={user} darkMode={darkMode} />} />
                  <Route path="/map" element={<Map user={user} darkMode={darkMode} />} />
                  <Route path="/mypage" element={<MyPage user={user} setUser={setUser} darkMode={darkMode} toggleDarkMode={toggleDarkMode} />} />
                </Routes>
              </Suspense>
            </main>
            <Navigation currentTab={currentTab} darkMode={darkMode} />
            <Suspense fallback={null}>
              <JapaneseMascot mood="happy" size="medium" position="floating" />
              <PushNotifications />
              <OfflineSupport />
            </Suspense>
          </div>
        </div>
      </SeasonalTheme>
    </Suspense>
  );
}

export default App;
